/**
 * The answer of last resort, so that no question ever blocks an application.
 *
 * The order every answer is derived in is: the candidate's own answer in the
 * bank → the seed drawn from their résumé → a fact on the profile → this. Only
 * when the first three have nothing does the agent land here, and landing here
 * still has to produce an answer: an application is never stopped for want of
 * one, because a run that stops is a run that asks a person, and there is no
 * person in this loop.
 *
 * What makes that safe is that for the questions with a legal consequence there
 * is always a truthful thing to say without evidence — the negative. "I am not
 * authorized to work in the United States" and "I would require sponsorship"
 * claim nothing: they are what the absence of a document means. The positive is
 * the one that would be a fabrication, and it is never produced here. For
 * optional and demographic questions the truthful non-answer is the decline
 * option the form itself offers.
 *
 * Anything else has no safe default and gets none: the caller writes from the
 * profile instead. Returning null is this module saying "there is nothing to
 * assert here", not "stop".
 */

import { namedPlaces, reachAllows } from "@fbj/core";

export interface ConservativeDefault {
  /** The answer to give, in the candidate's dashboard-neutral English. */
  answer: string;
  /** Which control it has to drive. */
  kind: "boolean" | "text";
  /** Why it is this answer — carried into the tool hint and the /answers row. */
  why: string;
}

/**
 * "Are you authorized to work in the US?" in the wordings forms actually use.
 *
 * Deliberately narrow on the country: authorization to work *where the
 * candidate lives* is a different question with a different true answer, and
 * answering that one "no" would be as false as answering the US one "yes".
 */
const US_WORK_AUTHORIZATION_RE =
  /(legally\s+)?(authoriz|authoris|eligible|permitted|entitled|right to work)[a-z]*\b[^.?]{0,60}\b(u\.?s\.?a?\.?|united states|america)\b|\b(u\.?s\.?a?\.?|united states)\b[^.?]{0,60}\b(work (authoriz|authoris|permit|eligib)|authoriz[a-z]*\s+to\s+work)/i;

/**
 * The same question with the country left implicit: "are you authorized to
 * work in the country where the job is located?".
 *
 * It names no country, so the US pattern above does not fire and neither does
 * a residence question — and until 2026-08-19 that meant no default at all,
 * and the model answered it. It answered "Yes" three times into the founder's
 * own bank, which held his approved "No — I hold a B1/B2 visitor visa and have
 * no US work authorization" the whole time. Two of those were used on Airbnb
 * runs that only failed to submit because a verification gate stopped them.
 *
 * A legal declaration is never the model's to make, and it does not have to
 * be: the country IS knowable here — it is the posting's — so it is resolved
 * from the posting and the candidate's own work countries.
 */
const JOB_COUNTRY_AUTHORIZATION_RE =
  /\bcountry\b[^.?]{0,60}\b(job|position|role|vacancy|employment|office|employer|company)\b|\b(job|position|role|vacancy)\b[^.?]{0,60}\bis located\b/i;

/** Authorization asked about, in the wordings forms use. */
const AUTHORIZATION_WORDS =
  /(authoriz|authoris|eligible|permitted|entitled|right to work|autoriza[cçd]|autorizado|permiso para trabajar)/i;

/**
 * "…in the country where you reside" is a DIFFERENT question: its true answer
 * for someone working legally where they live is yes, and the negative would
 * be as false there as the positive is for the US.
 */
const RESIDENCE_RE =
  /\b(reside|residency|residence|you live|where you are based|país onde (você )?(reside|mora))\b/i;

/**
 * "Do you have authorization to live and work in YOUR country?"
 *
 * The one authorization question whose true answer is yes and is evidenced: a
 * person who lives somewhere may work there. Until 2026-08-21 it fell through
 * every branch — `RESIDENCE_RE` was only ever used to SUPPRESS the job-country
 * answer, so this got no answer at all, and one Greenhouse application died on
 * a form where this was the only question left (measured, 2026-08-21).
 *
 * Deliberately narrow: it must name the candidate's OWN country. "the country
 * where this role is based" is a different question with a different true
 * answer, and it is handled below.
 */
const OWN_COUNTRY_AUTHORIZATION_RE =
  /\b(your|his|her|their) (own )?(home )?countr(y|ies)\b|\bcountry (where |in which )?you (live|reside|are based)\b|\bcountry of residence\b|\bseu pa[ií]s\b|\bpa[ií]s onde (voc[êe] )?(reside|mora|vive)\b|\btu pa[ií]s\b/i;

/** "Do you now or in the future require visa sponsorship?" and its variants. */
const SPONSORSHIP_RE =
  /\bsponsor(ship|ing|ed)?\b|\bvisa\b[^.?]{0,40}\b(support|require|need)|\b(require|need)[^.?]{0,40}\bvisa\b|\bh-?1b\b/i;

/**
 * EEO / voluntary self-identification, in English, Portuguese and Spanish.
 *
 * The apply prompt already tells the agent to pick the form's own decline
 * option for these; this exists so the same rule has a value to STORE, and so
 * the reason the row says "prefer not to say" is recorded rather than looking
 * like an answer the candidate gave.
 */
const DEMOGRAPHIC_RE =
  /\b(gender|sex|race|ethnic(ity|origin)?|veteran|disabilit(y|ies)|pronouns?|sexual orientation|self[- ]identif)/i;
const DEMOGRAPHIC_PT_ES_RE =
  /\b(g[eê]nero|sexo|ra[çc]a|etnia|defici[eê]ncia|orienta[çc][aã]o sexual|identidade de g[eê]nero|discapacidad|veterano)\b/i;

/**
 * What the posting reaches and what the candidate may work under, for the
 * authorization question that names no country of its own.
 */
export interface JobReach {
  /** The posting's location line, as the job row holds it. */
  location: string | null | undefined;
  /** The posting speaking about its own reach (`worldwide`, `us_only`, …). */
  remoteScope?: string | null;
  /** Countries the candidate may work in, from `profile.eligibility`. */
  workCountries: string[];
}

/**
 * May the candidate work where this posting's work happens?
 *
 * NOT `reachAllows`, and the difference is the whole point. That function
 * answers "can this candidate take this job", where a worldwide-remote posting
 * is a yes whatever its location line says. This one answers "is the candidate
 * authorized in the country the posting names", and there a location line
 * reading "San Francisco, California, USA" decides even when the row also says
 * `worldwide` — the scope is the company describing how it hires, the line is
 * where the work sits, and answering yes to the US on the strength of the
 * scope is precisely the fabrication this branch exists to stop. Measured
 * against 40 real postings on 2026-08-19: using `reachAllows` claimed US
 * authorization on Atlassian (San Francisco) and Overvak (New York), and
 * denied it on three Brazilian postings for a Brazilian candidate.
 *
 * So: a named country decides; only a posting that names none falls back to
 * "hires anywhere", which means the candidate works from home and is
 * authorized there.
 */
function whereTheWorkIs(job: JobReach): "yes" | "no" | "unknown" {
  const places = namedPlaces(job.location, job.remoteScope);
  if (!job.workCountries.length) return "yes";
  if (places.countries.length) {
    return places.countries.some((c) => job.workCountries.includes(c))
      ? "yes"
      : "no";
  }
  if (places.open) return "yes";
  return reachAllows(places, job.workCountries) === "yes" ? "yes" : "unknown";
}

/**
 * The conservative truthful answer for a question nothing else can answer, or
 * null when the question has no safe default and must be written from the
 * profile.
 *
 * `job` is only consulted by the implicit-country authorization branch. Absent
 * it, that branch still answers — with the negative, because a positive with
 * nothing behind it is the fabrication this module exists to prevent.
 */


