export function conservativeDefaultAnswer(
  question: string,
  job?: JobReach,
): ConservativeDefault | null {
  const q = question.trim();
  if (!q) return null;

  // Order matters: a sponsorship question often names the United States too,
  // and its true answer is the opposite polarity of the authorization one.
  if (SPONSORSHIP_RE.test(q)) {
    return {
      answer: "Yes — I would require visa sponsorship to work in the US.",
      kind: "boolean",
      why:
        "No document on file says otherwise, and needing sponsorship is what " +
        "the absence of one means. Saying no here would assert a status the " +
        "candidate has not evidenced.",
    };
  }
  if (US_WORK_AUTHORIZATION_RE.test(q)) {
    return {
      answer: "No — I am not authorized to work in the United States.",
      kind: "boolean",
      why:
        "Work authorization is a document, and nothing on file evidences one. " +
        "The negative claims nothing; the positive would be a fabrication.",
    };
  }
  // Before the job-country branch: a question about the candidate's own
  // country names a country too, and its true answer is the opposite one.
  if (AUTHORIZATION_WORDS.test(q) && OWN_COUNTRY_AUTHORIZATION_RE.test(q)) {
    return {
      answer: "Yes — I am authorized to live and work in my own country.",
      kind: "boolean",
      why:
        "The profile says where the candidate lives, and a person may work " +
        "where they live. This asks about their own country, not about the " +
        "country this role is based in — those have different true answers.",
    };
  }
  if (
    AUTHORIZATION_WORDS.test(q) &&
    JOB_COUNTRY_AUTHORIZATION_RE.test(q) &&
    !RESIDENCE_RE.test(q)
  ) {
    const reach = whereTheWorkIs(job ?? { location: null, workCountries: [] });
    if (reach === "yes") {
      return {
        answer: "Yes — I am authorized to work where this role is based.",
        kind: "boolean",
        why:
          "The posting's reach includes a country the candidate may work in, " +
          "so the positive is evidenced rather than assumed.",
      };
    }
    return {
      answer:
        "No — I am not authorized to work in the country where this role is based.",
      kind: "boolean",
      why:
        reach === "no"
          ? "The posting is based where the candidate has no right to work."
          : "Where the posting is based cannot be read from it, and " +
            "authorization is a document. The negative claims nothing; the " +
            "positive would be a fabrication.",
    };
  }
  if (DEMOGRAPHIC_RE.test(q) || DEMOGRAPHIC_PT_ES_RE.test(q)) {
    return {
      answer: "Prefer not to say.",
      kind: "text",
      why:
        "Voluntary self-identification. Declining is an answer the form offers " +
        "and no employer may hold against it — pick the decline option as the " +
        "page words it.",
    };
  }
  return null;
}


